package net.johnpgr.craftingtableiifabric.forge;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.minecraft.world.item.BlockItem;import net.minecraft.world.level.block.Block;import net.minecraftforge.client.extensions.common.IClientItemExtensions;import org.jetbrains.annotations.NotNull;import java.util.function.Consumer;public class CraftingTableIIBlockItem extends BlockItem {    public CraftingTableIIBlockItem(Block block, Properties properties) {        super(block, properties);    }    @Override    public void initializeClient(Consumer<IClientItemExtensions> consumer) {        consumer.accept(new IClientItemExtensions() {            @Override @NotNull            public BlockEntityWithoutLevelRenderer getCustomRenderer() {                return ForgeClientHelper.getOrCreateItemRenderer();            }        });    }}